import functools


def retry(times, exceptions):
    def deco(fn):
        @functools.wraps(fn)
        def wrapper(*a, **kw):
            last = None
            for _ in range(times):
                try:
                    return fn(*a, **kw)
                except exceptions as exc:
                    last = exc
            raise last
        return wrapper
    return deco

