DISCOUNTS = {'SAVE10': 0.10, 'HALF': 0.50}


def subtotal(items):
    return sum(it['price'] * it['qty'] for it in items)


def apply_discount(amount, code):
    return amount * (1 - DISCOUNTS[code]) if code in DISCOUNTS else amount


def with_tax(amount, rate):
    return round(amount * (1 + rate), 2)


def total(items, code, rate):
    return with_tax(apply_discount(subtotal(items), code), rate)

