def merge_intervals(iv):
    if not iv:
        return []
    out = []
    for s, e in sorted(iv, key=lambda p: (p[0], p[1])):
        if out and s <= out[-1][1]:
            out[-1][1] = max(out[-1][1], e)
        else:
            out.append([s, e])
    return out

