def mean(xs):
    t = 0.0
    n = 0
    for x in xs:
        t += x
        n += 1
    return t / n if n else 0.0

def variance(xs):
    t = 0.0
    n = 0
    for x in xs:
        t += x
        n += 1
    m = t / n if n else 0.0
    s = 0.0
    for x in xs:
        s += (x - m) ** 2
    return s / n if n else 0.0

def stddev(xs):
    return variance(xs) ** 0.5

