def _accumulate(xs):
    total = 0.0
    n = 0
    for x in xs:
        total += x
        n += 1
    return total, n


def mean(xs):
    total, n = _accumulate(xs)
    return total / n if n else 0.0


def variance(xs):
    total, n = _accumulate(xs)
    if not n:
        return 0.0
    m = total / n
    sq, _ = _accumulate((x - m) ** 2 for x in xs)
    return sq / n


def stddev(xs):
    return variance(xs) ** 0.5
